NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Philippians'

CHAPTERS = {
    1: {
        1: 'Paavali ja Timoteus, Kristuksen Jeesuksen palvelijat, kaikille pyhille Kristuksessa Jeesuksessa, jotka ovat Filipissä, sekä myös seurakunnan kaitsijoille ja diakoneille.',
        2: 'Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!',
        3: 'Kiitän Jumalaani joka kerta kun teitä muistelen,',
        4: 'aina kaikissa rukouksissani ilolla rukoillen teidän kaikkien puolesta,',
        5: 'kiitän siitä, että olette olleet osallisia evankeliumiin sen ensi päivästä alkaen tähän päivään saakka,',
        6: 'varmasti luottaen siihen, että hän, joka on alkanut teissä hyvän työn, on sen saattava päätökseen Kristuksen Jeesuksen päivään saakka.',
        7: 'Ja oikein onkin minun näin ajatella teistä kaikista, koska olette sydämessäni, te, jotka sekä ollessani kahleissa että evankeliumia puolustaessani ja vahvistaessani olette kaikki kanssani armosta osallisia.',
        8: 'Sillä Jumala on todistajani, kuinka teitä kaikkia ikävöin Kristuksen Jeesuksen sydämellisellä rakkaudella',
        9: 'ja sitä rukoilen, että teidän rakkautenne tulisi yhä runsaammaksi tiedossa ja kaikessa käsittämisessä',
        10: 'voidaksenne tutkia, mikä on parasta, että Kristuksen päivään saakka olisitte puhtaat ettekä kenellekään loukkaukseksi,',
        11: 'täynnä vanhurskauden hedelmää Jeesuksen Kristuksen kautta Jumalan kunniaksi ja ylistykseksi.',
        12: 'Mutta tahdon teidän tietävän, veljet, että se, mitä minulle on tapahtunut, onkin koitunut evankeliumin menestykseksi,',
        13: 'niin että koko henkivartioston ja kaikkien muiden tietoon on tullut, että olen kahleissa Kristuksen tähden,',
        14: 'ja että useimmat veljistä saaden Herrassa uskallusta kahleistani rohkenevat yhä enemmän pelkäämättä puhua Jumalan sanaa.',
        15: 'Muutamat tosin julistavat Kristusta kateudestakin ja riidan halusta, mutta toiset hyvässä tarkoituksessa.',
        16: 'Ne, jotka julistavat Kristusta riidan halusta, eivät tee sitä puhtaasta mielestä ja luulevat tuottavansa minulle murhetta kahleissani.',
        17: 'Mutta nämä tekevät sitä rakkaudesta, koska tietävät, että minut on pantu evankeliumia puolustamaan.',
        18: 'Vaan mitäpä tuosta, kunhan Kristusta vain tavalla tai toisella julistetaan, joko näön vuoksi tai totuudessa! Ja siitä iloitsen ja vastakin iloitsen.',
        19: 'Sillä tiedän, että tämä on päättyvä minulle pelastukseksi teidän rukoustenne kautta ja Jeesuksen Kristuksen Hengen avulla,',
        20: 'minun hartaan odotukseni ja toivoni mukaan, etten ole missään joutuva häpeään, vaan että Kristus nytkin, niin kuin aina, tulee ylistetyksi ruumiissani kaikella rohkeudella, joko elämän tai kuoleman kautta.',
        21: 'Sillä eläminen on minulle Kristus ja kuoleminen on voitto.',
        22: 'Mutta jos eläminen lihassa tuo työlleni hedelmää, en tiedä, minkä valitsen.',
        23: 'Ahtaalla olen näiden kahden välissä: halu minulla on päästä täältä pois ja olla Kristuksen kanssa, sillä se olisi monin verroin parempi,',
        24: 'mutta teidän tähtenne on lihassa viipymiseni tarpeellisempaa.',
        25: 'Ja kun olen tästä varma, tiedän jääväni eloon ja viipyväni kaikkien teidän luonanne teidän edistymiseksenne ja iloksenne uskossa,',
        26: 'että teidän kerskaamisenne minusta olisi yhä runsaampaa Kristuksessa Jeesuksessa, kun taas tulen luoksenne.',
        27: 'Käyttäytykää vain Kristuksen evankeliumin arvon mukaisesti, että tulenpa sitten luoksenne ja näen teidät tai olen tulematta, saan kuulla teistä, että pysytte samassa hengessä ja yksimielisinä taistelette kanssani evankeliumin uskon puolesta',
        28: 'vastustajia missään kohden säikähtämättä. Se on heille kadotuksen, mutta teille pelastuksen merkki. Se on merkki Jumalalta.',
        29: 'Sillä teidän on suotu Kristuksen tähden, ei ainoastaan uskoa häneen, vaan myös kärsiä hänen tähtensä,',
        30: 'teidän, joilla on sama taistelu, jota olette minulla nähneet ja nyt kuulette minulla olevan.',
    },
    2: {
        1: 'Jos siis on jotakin kehotusta Kristuksessa, jos jotakin rakkauden lohdutusta, jos jotakin Hengen yhteyttä, jos jotakin sydämellisyyttä ja laupeutta,',
        2: 'niin tehkää iloni täydelliseksi niin, että ajattelette samoin, että teillä on sama rakkaus, että teillä on sama henki ja että teillä on yksi ja sama ajatus,',
        3: 'ettekä tee mitään riidanhalusta tai turhan kunnian pyynnöstä, vaan että nöyryydessä pidätte toista parempana kuin itseänne',
        4: 'ja että katsotte, ette vain omaa etuanne, vaan jokainen toistenkin parasta.',
        5: 'Olkoon teillä se mieli, joka myös Kristuksella Jeesuksella oli,',
        6: 'joka ei, vaikka hänellä olikin Jumalan muoto, katsonut saaliikseen olla Jumalan kaltainen,',
        7: 'vaan tyhjensi itsensä ottamalla orjan muodon, tuli ihmisten kaltaiseksi, ja hänet havaittiin olemukseltaan sellaiseksi kuin ihminen.',
        8: 'Hän nöyryytti itsensä ja oli kuuliainen kuolemaan asti, aina ristin kuolemaan asti.',
        9: 'Sen tähden onkin Jumala hänet korkealle korottanut ja antanut hänelle nimen, kaikkia muita nimiä korkeamman,',
        10: 'jotta kaikki polvet notkistuisivat Jeesuksen nimeen, sekä niiden, jotka taivaissa ovat, että niiden, jotka maan päällä ovat, ja niiden, jotka maan alla ovat,',
        11: 'ja jokainen kieli tunnustaisi Isän Jumalan kunniaksi, että Jeesus Kristus on Herra.',
        12: 'Siis, rakkaani, samoin kuin aina olette olleet kuuliaisia, niin ahkeroikaa, ei ainoastaan ollessani teidän luonanne, vaan paljoa enemmän nyt ollessani poissa, pelolla ja vavistuksella, että pelastuisitte.',
        13: 'Sillä Jumala on se, joka teissä vaikuttaa sekä tahtomisen että tekemisen, että hänen hyvä tahtonsa tapahtuisi.',
        14: 'Tehkää kaikki nurisematta ja järkeilemättä,',
        15: 'jotta olisitte moitteettomia ja puhtaita, olisitte tahrattomia Jumalan lapsia kieron ja nurjan sukukunnan keskellä, joiden joukossa te loistatte kuin tähdet maailmassa,',
        16: 'tarjolla pitäessänne elämän sanaa minulle kerskaukseksi Kristuksen päivänä siitä, etten ole turhaan juossut enkä turhaan vaivaa nähnyt.',
        17: 'Vaikka minut vuodatettaisiin juomauhriksi toimittaessani palvelusta uskonne hyväksi, iloitsen kuitenkin ja iloitsen kaikkien teidän kanssanne.',
        18: 'Siitä tekin iloitkaa, ja iloitkaa kanssani!',
        19: 'Toivon Herrassa Jeesuksessa pian voivani lähettää Timoteuksen luoksenne, että minäkin tulisin rohkaistuksi, kun saan tietää, kuinka teidän on.',
        20: 'Sillä minulla ei ole ketään samanmielistä, joka huolehtisi vilpittömästi tilastanne,',
        21: 'sillä kaikki he etsivät omaansa eivätkä sitä, mikä on Kristuksen Jeesuksen.',
        22: 'Mutta hänen koetellun mielensä tunnette, että, niin kuin poika isänsä rinnalla hän on palvellut kanssani evankeliumin hyväksi.',
        23: 'Hänet siis toivon voivani lähettää heti, kun olen saanut nähdä, miten minun käy.',
        24: 'Ja luotan Herrassa, että itsekin olen pian tuleva.',
        25: 'Katson kuitenkin välttämättömäksi lähettää luoksenne veljeni, työtoverini ja taistelutoverini Epafroditoksen, teidän lähettinne ja palvelijanne tarpeissani.',
        26: 'Sillä hän ikävöi teitä kaikkia ja on kovin levoton siitä, että olitte kuulleet hänen olevan sairaana.',
        27: 'Ja hän olikin sairaana, kuoleman kielissä, mutta Jumala armahti häntä, eikä ainoastaan häntä, vaan myös minua, etten saisi murhetta murheen päälle.',
        28: 'Lähetän hänet sen tähden mitä kiireimmin, että te hänet nähdessänne taas iloitsisitte ja minäkin olisin murheettomampi.',
        29: 'Ottakaa siis hänet vastaan Herrassa kaikella ilolla, ja pitäkää sellaisia kunniassa.',
        30: 'Sillä Kristuksen työn tähden hän joutui aivan kuoleman partaalle, kun pani henkensä alttiiksi tehdäkseen minulle sen palveluksen, mikä teiltä puuttui.',
    },
    3: {
        1: 'Sitten vielä, veljeni, iloitkaa Herrassa! Samoista asioista teille kirjoittaminen ei kyllästytä minua, ja teille se on turvaksi.',
        2: 'Varokaa noita koiria, varokaa noita pahoja työntekijöitä, varokaa noita leikeltyjä.',
        3: 'Sillä me olemme ympärileikattuja, me, jotka Jumalan Hengessä palvelemme Jumalaa ja kerskaamme Kristuksessa Jeesuksessa, emmekä luota lihaan,',
        4: 'vaikka minulla on, mihin luottaa lihassakin. Jos kuka muu luulee voivansa luottaa lihaan, niin voin vielä enemmän minä,',
        5: 'joka olen ympärileikattu kahdeksanpäiväisenä ja olen Israelin kansaa, Benjaminin sukukuntaa, heprealainen heprealaisista, lakiin nähden fariseus,',
        6: 'intoon nähden seurakunnan vainooja, lain vanhurskauteen nähden nuhteeton.',
        7: 'Mutta mikä minulle oli voitto, sen olen lukenut tappioksi Kristuksen tähden.',
        8: 'Niinpä todella luen kaikki tappioksi tuon hyvin kalliin, Kristuksen Jeesuksen, minun Herrani, tuntemisen rinnalla, sillä hänen tähtensä minä olen menettänyt kaiken ja pidän sen roskana, jotta voittaisin omakseni Kristuksen',
        9: 'ja minun havaittaisiin olevan hänessä ja omistavan, ei omaa vanhurskautta, sitä, joka laista tulee, vaan sen, joka tulee uskon kautta Kristukseen, sen vanhurskauden, joka tulee Jumalasta uskolle,',
        10: 'tunteakseni hänet ja hänen ylösnousemisensa voiman ja hänen kärsimystensä osallisuuden tullakseni hänen kuolemansa kaltaiseksi,',
        11: 'kunhan jollain tavalla pääsen ylösnousemiseen kuolleista.',
        12: 'Ei niin, että jo olisin sen omakseni saanut tai että jo olisin täydellinen, vaan pyrin saamaan sen omakseni, koska Kristus Jeesus on ottanut omakseen minut.',
        13: 'Veljet, minä en katso sitä vielä omistavani. Mutta yhden teen: unohtaen sen, mikä on takana, ja kurottautuen sitä kohti, mikä on edessä,',
        14: 'minä riennän maaliin saamaan voittopalkinnon, johon Jumala on minut taivaallisella kutsumisella kutsunut Kristuksessa Jeesuksessa.',
        15: 'Olkoon siis meillä, niin monta kuin meitä on täydellistä, tämä mieli, ja jos teillä on jossakin kohden toinen mieli, Jumala on teille senkin ilmoittava.',
        16: 'Kunhan vain, mihin saakka olemme ehtineetkin, vaellamme säännön mukaan ja ajattelemme samoin!',
        17: 'Olkaa minun seuraajiani, veljet, ja katselkaa niitä, jotka näin vaeltavat, niin kuin me olemme teille esikuvana.',
        18: 'Sillä monet, joista usein olen sen teille sanonut ja nyt aivan itkien sanon, vaeltavat Kristuksen ristin vihollisina.',
        19: 'Heidän loppunsa on kadotus, vatsa on heidän jumalansa, heidän kunnianaan on heidän häpeänsä, ja maallisiin on heidän mielensä.',
        20: 'Meidän kansalaisuutemme näet on taivaissa, ja sieltä myös odotamme Vapahtajaa, Herraa Jeesusta Kristusta,',
        21: 'joka on muuttava alennustilamme ruumiin olemuksen kirkkautensa ruumiin kaltaiseksi sillä voimallaan, jolla hän myös voi tehdä kaiken itselleen alamaiseksi.',
    },
    4: {
        1: 'Sen tähden, rakkaat ja ikävöidyt veljeni, te, minun iloni ja kruununi, seisokaa näin lujina Herrassa, rakkaat!',
        2: 'Euodiaa kehotan ja Syntykeä kehotan olemaan yksimielisiä Herrassa.',
        3: 'Myös sinua, oikea Synsygukseni, pyydän: ole avuksi näille naisille, sillä he ovat taistelleet kanssani evankeliumin hyväksi yhdessä sekä Klemensin että muiden työtoverieni kanssa, joiden nimet ovat elämän kirjassa.',
        4: 'Iloitkaa aina Herrassa! Vieläkin sanon: iloitkaa!',
        5: 'Tulkoon lempeytenne kaikkien ihmisten tietoon. Herra on lähellä.',
        6: 'Älkää murehtiko mistään, vaan saattakaa kaikessa pyyntönne rukouksella ja anomisella kiitoksen kanssa tietoon Jumalan edessä,',
        7: 'ja Jumalan rauha, joka on kaikkea ymmärrystä ylempi, on varjeleva sydämenne ja ajatuksenne Kristuksessa Jeesuksessa.',
        8: 'Ja vielä, veljet, kaikki, mikä on totta, mikä kunnioitettavaa, mikä oikeaa, mikä pyhää, mikä rakastettavaa, millä on hyvä maine, jos on jokin hyve ja jos on jotakin kiitettävää, sitä ajatelkaa.',
        9: 'Tehkää sitä, mitä olette myös minulta oppineet, vastaanottaneet, kuulleet ja minussa nähneet, niin rauhan Jumala on oleva teidän kanssanne.',
        10: 'Ilahduin suuresti Herrassa, että olitte vihdoin uudestaan alkaneet pitää minusta huolta, jota olitte ennenkin ajatelleet, mutta teillä ei ollut ollut siihen tilaisuutta.',
        11: 'Ei niin, että sanon tämän puutteen vuoksi. Sillä olen oppinut tyytymään oloihini.',
        12: 'Osaan elää niukkuudessa, osaan myös elää runsaudessa. Kaikkeen ja kaikenlaisiin oloihin olen tottunut, sekä olemaan ravittuna että näkemään nälkää, elämään sekä runsaudessa että puutteessa.',
        13: 'Kaikki voin hänessä, joka minua vahvistaa Kristuksessa.',
        14: 'Kuitenkin teitte hyvin, kun otitte osaa ahdinkooni.',
        15: 'Tiedättehän tekin, filippiläiset, että evankeliumin alussa, kun lähdin Makedoniasta, mikään muu seurakunta kuin te yksin ei osallistunut kanssani tilinpitoon annetusta ja vastaanotetusta.',
        16: 'Sillä Tessalonikaankin minulle kerran, jopa kahdesti, lähetitte, mitä tarvitsin.',
        17: 'Ei niin, että haluaisin lahjaa, vaan haluan teidän hyväksenne karttuvaa hedelmää.',
        18: 'Olen nyt saanut kaikkea, jopa ylenpalttisesti. Minulla on yllin kyllin saatuani Epafroditukselta lähetyksenne, "suloisen tuoksun", otollisen, Jumalalle mieluisen uhrin.',
        19: 'Mutta Jumalani on täyttävä kaikki tarpeenne rikkautensa mukaisesti kirkkaudessa, Kristuksessa Jeesuksessa.',
        20: 'Mutta meidän Jumalallemme ja Isällemme kunnia iäisyyksien iäisyyksiin! Aamen.',
        21: 'Tervehtikää jokaista pyhää Kristuksessa Jeesuksessa. Tervehdyksen lähettävät teille kanssani olevat veljet.',
        22: 'Tervehdyksen lähettävät teille kaikki pyhät, mutta varsinkin ne, jotka ovat keisarin hovista.',
        23: 'Herran Jeesuksen Kristuksen armo olkoon teidän henkenne kanssa.',
    },
}
